//==============================================================================
// Testbench: tb_coarse_cfo_estimator
// Description: Comprehensive, self-checking SystemVerilog verification testbench
//              for the Coarse Carrier Frequency Offset (CFO) Estimator.
//              Plays back stimulus generated by the MATLAB golden reference model,
//              directly parses and compares RTL results against MATLAB golden expectations:
//              1. Zero CFO (0 Hz, SNR = 25 dB, Mode B)
//              2. Moderate Positive CFO (+0.05 Rsym = +1.5625 MHz, SNR = 20 dB, Mode B)
//              3. Moderate Negative CFO (-0.05 Rsym = -1.5625 MHz, SNR = 20 dB, Mode B)
//              4. Maximum Positive CFO Limit (+0.10 Rsym = +3.125 MHz, SNR = 18 dB, Mode B)
//              5. Maximum Negative CFO Limit (-0.10 Rsym = -3.125 MHz, SNR = 18 dB, Mode B)
//              6. Intermediate Positive CFO (+0.07 Rsym = +2.1875 MHz, SNR = 15 dB, Mode B)
//              7. Intermediate Negative CFO (-0.03 Rsym = -937.5 kHz, SNR = 15 dB, Mode B)
//              8. Low SNR Condition (+0.02 Rsym = +625 kHz, SNR = 6 dB, Mode B)
//              9. Autonomous Mode A Detection with Noise Prefix (+0.03 Rsym, SNR = 12 dB)
//              10. Autonomous Mode A Detection with High Negative CFO (-0.08 Rsym, SNR = 14 dB)
//              11. Streaming with Invalid-Sample Gaps (+0.04 Rsym, SNR = 20 dB, 50% Gaps)
//              12. Consecutive Back-to-Back Bursts (Dynamic Re-Arming)
//              13. Mid-Stream Reset Handling & Abort Recovery
//==============================================================================

`timescale 1ns / 1ps

module tb_coarse_cfo_estimator;

    // Clock and System Parameters
    localparam real CLK_PERIOD_NS = 8.0; // 125 MHz typical clock
    localparam real FS_HZ         = 125.0e6;
    localparam real RSYM_HZ       = 31.25e6;
    localparam real MAX_TOL_HZ    = 0.005 * RSYM_HZ; // +/-156.25 kHz limit (+/-0.5% Rsym)

    // DUT Architecture Parameters
    localparam int DATA_WIDTH     = 12;
    localparam int DELAY_L        = 16;
    localparam int ACCUM_M        = 192;
    localparam int CORDIC_STAGES  = 16;
    localparam int CFO_WIDTH      = 24;
    localparam int NCO_WIDTH      = 32;

    // DUT Interface Signals
    logic                          clk;
    logic                          rst_n;
    logic signed [DATA_WIDTH-1:0]  str_out_i;
    logic signed [DATA_WIDTH-1:0]  str_out_q;
    logic                          str_out_valid;
    logic                          burst_start;
    logic                          preamble_enable;
    logic                          auto_mode_en;
    logic [15:0]                   gamma_scaled;
    logic [27:0]                   energy_min_thresh;

    logic                          preamble_detected;
    logic [31:0]                   det_metric_out;
    logic                          accum_busy;
    logic signed [CFO_WIDTH-1:0]   coarse_cfo_est;
    logic                          coarse_cfo_valid;
    logic signed [NCO_WIDTH-1:0]   nco_ftw;

    // Testbench Variables & Statistics
    int test_pass_count = 0;
    int test_fail_count = 0;
    int current_sample_idx = 0;

    // Instantiate Device Under Test (DUT)
    coarse_cfo_estimator_top #(
        .DATA_WIDTH    (DATA_WIDTH),
        .DELAY_L       (DELAY_L),
        .ACCUM_M       (ACCUM_M),
        .CORDIC_STAGES (CORDIC_STAGES),
        .CFO_WIDTH     (CFO_WIDTH),
        .NCO_WIDTH     (NCO_WIDTH)
    ) dut (
        .clk               (clk),
        .rst_n             (rst_n),
        .str_out_i         (str_out_i),
        .str_out_q         (str_out_q),
        .str_out_valid     (str_out_valid),
        .burst_start       (burst_start),
        .preamble_enable   (preamble_enable),
        .auto_mode_en      (auto_mode_en),
        .gamma_scaled      (gamma_scaled),
        .energy_min_thresh (energy_min_thresh),
        .preamble_detected (preamble_detected),
        .det_metric_out    (det_metric_out),
        .accum_busy        (accum_busy),
        .coarse_cfo_est    (coarse_cfo_est),
        .coarse_cfo_valid  (coarse_cfo_valid),
        .nco_ftw           (nco_ftw)
    );

    // 125 MHz Clock Generator
    initial begin
        clk = 1'b0;
        forever #(CLK_PERIOD_NS / 2.0) clk = ~clk;
    end

    // Helper Task: Reset DUT
    task reset_dut();
        rst_n             <= 1'b0;
        str_out_i         <= '0;
        str_out_q         <= '0;
        str_out_valid     <= 1'b0;
        burst_start       <= 1'b0;
        preamble_enable   <= 1'b0;
        auto_mode_en      <= 1'b0;
        gamma_scaled      <= 16'd36045; // 0.55 * 65536
        energy_min_thresh <= 28'd1000000;
        repeat (5) @(posedge clk);
        rst_n <= 1'b1;
        repeat (2) @(posedge clk);
    endtask

    // Helper Function: Convert Q1.23 to Frequency in Hz
    function real q23_to_hz(input logic signed [23:0] q23_val);
        real norm_val;
        norm_val = real'(q23_val) / 8388608.0; // 2^23
        return norm_val * (FS_HZ / 2.0);
    endfunction

    // Helper Task: Parse MATLAB Golden Reference File
    task parse_matlab_expected(
        input  string                     exp_file,
        output logic signed [23:0]        golden_cfo_est,
        output logic signed [31:0]        golden_nco_ftw,
        output real                       actual_cfo_hz,
        output real                       matlab_cfo_hz,
        output int                        exp_sample_idx
    );
        int fd;
        string line;
        int parsed_cfo, parsed_ftw, parsed_idx;
        real parsed_act, parsed_mat;

        golden_cfo_est = '0;
        golden_nco_ftw = '0;
        actual_cfo_hz  = 0.0;
        matlab_cfo_hz  = 0.0;
        exp_sample_idx = 0;

        fd = $fopen(exp_file, "r");
        if (fd == 0) begin
            $error("Failed to open MATLAB expected file: %s", exp_file);
            return;
        end

        while (!$feof(fd)) begin
            line = "";
            void'($fgets(line, fd));
            if ($sscanf(line, "cfo_est=%d", parsed_cfo) == 1) begin
                golden_cfo_est = 24'(parsed_cfo);
            end else if ($sscanf(line, "nco_ftw=%d", parsed_ftw) == 1) begin
                golden_nco_ftw = 32'(parsed_ftw);
            end else if ($sscanf(line, "actual_cfo_hz=%f", parsed_act) == 1) begin
                actual_cfo_hz = parsed_act;
            end else if ($sscanf(line, "matlab_cfo_hz=%f", parsed_mat) == 1) begin
                matlab_cfo_hz = parsed_mat;
            end else if ($sscanf(line, "valid_sample_idx=%d", parsed_idx) == 1) begin
                exp_sample_idx = parsed_idx;
            end
        end

        $fclose(fd);
    endtask

    // Helper Task: Playback Stimulus and Verify Against MATLAB Reference
    task run_vector_test(
        input string test_name,
        input string stim_file,
        input string exp_file
    );
        int fd_stim;
        logic signed [23:0] golden_cfo_est;
        logic signed [31:0] golden_nco_ftw;
        real actual_cfo_hz, matlab_cfo_hz;
        int exp_sample_idx;

        int in_i_val, in_q_val, vld_val, bs_val, pe_val, auto_val;
        int status;
        int start_cycle, valid_cycle;
        real rtl_est_hz, err_vs_actual_hz, err_vs_matlab_hz;
        int cfo_diff_lsb;
        bit found_valid;

        $display("\n------------------------------------------------------------");
        $display("Running: %s", test_name);
        $display("------------------------------------------------------------");

        // Load MATLAB Golden Expected File
        parse_matlab_expected(exp_file, golden_cfo_est, golden_nco_ftw, actual_cfo_hz, matlab_cfo_hz, exp_sample_idx);
        $display("  [MATLAB Golden Reference]");
        $display("    Actual CFO Injected : %0.2f kHz", actual_cfo_hz / 1e3);
        $display("    MATLAB Estimated CFO: %0.2f kHz (Q1.23: %0d)", matlab_cfo_hz / 1e3, golden_cfo_est);
        $display("    MATLAB Golden FTW   : %0d", golden_nco_ftw);

        fd_stim = $fopen(stim_file, "r");
        if (fd_stim == 0) begin
            $error("Failed to open stimulus file: %s", stim_file);
            test_fail_count++;
            return;
        end

        // Arm detector
        @(posedge clk);
        burst_start <= 1'b1;
        @(posedge clk);
        burst_start <= 1'b0;

        start_cycle = 0;
        valid_cycle = 0;
        found_valid = 0;
        current_sample_idx = 0;

        while (!$feof(fd_stim)) begin
            status = $fscanf(fd_stim, "%d %d %d %d %d %d\n", in_i_val, in_q_val, vld_val, bs_val, pe_val, auto_val);
            if (status == 6) begin
                @(posedge clk);
                str_out_i       <= DATA_WIDTH'(in_i_val);
                str_out_q       <= DATA_WIDTH'(in_q_val);
                str_out_valid   <= 1'(vld_val);
                preamble_enable <= 1'(pe_val);
                auto_mode_en    <= 1'(auto_val);

                if (bs_val) begin
                    burst_start <= 1'b1;
                end else begin
                    burst_start <= 1'b0;
                end

                current_sample_idx++;
                if (current_sample_idx == 1) start_cycle = current_sample_idx;

                if (coarse_cfo_valid && !found_valid) begin
                    found_valid = 1;
                    valid_cycle = current_sample_idx;
                    rtl_est_hz = q23_to_hz(coarse_cfo_est);
                    err_vs_actual_hz = (rtl_est_hz > actual_cfo_hz) ? (rtl_est_hz - actual_cfo_hz) : (actual_cfo_hz - rtl_est_hz);
                    err_vs_matlab_hz = (rtl_est_hz > matlab_cfo_hz) ? (rtl_est_hz - matlab_cfo_hz) : (matlab_cfo_hz - rtl_est_hz);
                    cfo_diff_lsb = coarse_cfo_est - golden_cfo_est;
                    if (cfo_diff_lsb < 0) cfo_diff_lsb = -cfo_diff_lsb;

                    $display("  [RTL MEASUREMENT @ Sample %0d]", valid_cycle);
                    $display("    RTL Measured Q1.23  : %0d", coarse_cfo_est);
                    $display("    RTL Measured Freq   : %0.2f kHz", rtl_est_hz / 1e3);
                    $display("    Diff vs MATLAB Ref  : %0.2f kHz (%0d LSBs)", err_vs_matlab_hz / 1e3, cfo_diff_lsb);
                    $display("    Error vs Actual CFO : %0.2f kHz (Limit: +/-156.25 kHz)", err_vs_actual_hz / 1e3);
                    $display("    Latency             : %0d cycles (%0.1f symbols)", (valid_cycle - start_cycle), (valid_cycle - start_cycle) / 4.0);
                    $display("    RTL NCO FTW (32b)   : %0d (Expected: %0d)", nco_ftw, 32'($signed(coarse_cfo_est)) <<< 8);

                    // Check exact NCO FTW bit conversion: (coarse_cfo_est <<< 8)
                    assert (nco_ftw == (32'($signed(coarse_cfo_est)) <<< 8))
                        else $error("NCO FTW mismatch! Expected %0d, got %0d", 32'($signed(coarse_cfo_est)) <<< 8, nco_ftw);

                    // Check estimation accuracy within +/-0.005 Rsym
                    if (err_vs_actual_hz <= MAX_TOL_HZ) begin
                        $display("  >>> %s: PASSED <<<", test_name);
                        test_pass_count++;
                    end else begin
                        $display("  >>> %s: FAILED (Accuracy Tolerance Exceeded) <<<", test_name);
                        test_fail_count++;
                    end
                end
            end
        end

        $fclose(fd_stim);

        // Allow pipeline flush if still pending
        for (int w = 0; w < 60; w++) begin
            @(posedge clk);
            str_out_valid   <= 1'b0;
            burst_start     <= 1'b0;
            preamble_enable <= 1'b0;

            if (coarse_cfo_valid && !found_valid) begin
                found_valid = 1;
                valid_cycle = current_sample_idx + w + 1;
                rtl_est_hz = q23_to_hz(coarse_cfo_est);
                err_vs_actual_hz = (rtl_est_hz > actual_cfo_hz) ? (rtl_est_hz - actual_cfo_hz) : (actual_cfo_hz - rtl_est_hz);
                err_vs_matlab_hz = (rtl_est_hz > matlab_cfo_hz) ? (rtl_est_hz - matlab_cfo_hz) : (matlab_cfo_hz - rtl_est_hz);
                cfo_diff_lsb = coarse_cfo_est - golden_cfo_est;
                if (cfo_diff_lsb < 0) cfo_diff_lsb = -cfo_diff_lsb;

                $display("  [RTL MEASUREMENT POST-FLUSH @ Cycle %0d]", valid_cycle);
                $display("    RTL Measured Q1.23  : %0d", coarse_cfo_est);
                $display("    RTL Measured Freq   : %0.2f kHz", rtl_est_hz / 1e3);
                $display("    Diff vs MATLAB Ref  : %0.2f kHz (%0d LSBs)", err_vs_matlab_hz / 1e3, cfo_diff_lsb);
                $display("    Error vs Actual CFO : %0.2f kHz (Limit: +/-156.25 kHz)", err_vs_actual_hz / 1e3);
                $display("    Latency             : %0d cycles (%0.1f symbols)", (valid_cycle - start_cycle), (valid_cycle - start_cycle) / 4.0);
                $display("    RTL NCO FTW (32b)   : %0d", nco_ftw);

                assert (nco_ftw == (32'($signed(coarse_cfo_est)) <<< 8))
                    else $error("NCO FTW mismatch!");

                if (err_vs_actual_hz <= MAX_TOL_HZ) begin
                    $display("  >>> %s: PASSED <<<", test_name);
                    test_pass_count++;
                end else begin
                    $display("  >>> %s: FAILED (Accuracy Tolerance Exceeded) <<<", test_name);
                    test_fail_count++;
                end
            end
        end

        if (!found_valid) begin
            $display("  >>> %s: FAILED (No coarse_cfo_valid strobe received!) <<<", test_name);
            test_fail_count++;
        end
    endtask

    // Main Test Sequence
    initial begin
        $display("========================================================================");
        $display("   COARSE CFO ESTIMATOR - SYSTEMVERILOG EXTENDED RTL TESTBENCH          ");
        $display("   References Directly Loaded from MATLAB Golden Output Models          ");
        $display("========================================================================");

        // Optional VCD waveform dump
        $dumpfile("d:/SynchCore/sim/cfo_waves.vcd");
        $dumpvars(0, tb_coarse_cfo_estimator);

        reset_dut();

        // ---------------------------------------------------------------------
        // TEST CASE 1: Zero CFO (0 Hz, SNR = 25 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 1: Zero CFO (0 Hz, SNR = 25 dB, Mode B)",
            "d:/SynchCore/tb/vectors/stimulus_case1.txt",
            "d:/SynchCore/tb/vectors/expected_case1.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 2: Moderate Positive CFO (+0.05 Rsym = +1.5625 MHz, SNR = 20 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 2: Moderate Positive CFO (+0.05 Rsym = +1.5625 MHz)",
            "d:/SynchCore/tb/vectors/stimulus_case2.txt",
            "d:/SynchCore/tb/vectors/expected_case2.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 3: Moderate Negative CFO (-0.05 Rsym = -1.5625 MHz, SNR = 20 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 3: Moderate Negative CFO (-0.05 Rsym = -1.5625 MHz)",
            "d:/SynchCore/tb/vectors/stimulus_case3.txt",
            "d:/SynchCore/tb/vectors/expected_case3.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 4: Maximum Positive CFO Limit (+0.10 Rsym = +3.125 MHz, SNR = 18 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 4: Max Positive CFO Limit (+0.10 Rsym = +3.125 MHz)",
            "d:/SynchCore/tb/vectors/stimulus_case4.txt",
            "d:/SynchCore/tb/vectors/expected_case4.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 5: Maximum Negative CFO Limit (-0.10 Rsym = -3.125 MHz, SNR = 18 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 5: Max Negative CFO Limit (-0.10 Rsym = -3.125 MHz)",
            "d:/SynchCore/tb/vectors/stimulus_case5.txt",
            "d:/SynchCore/tb/vectors/expected_case5.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 6: Intermediate Positive CFO (+0.07 Rsym = +2.1875 MHz, SNR = 15 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 6: Intermediate Positive CFO (+0.07 Rsym, SNR = 15 dB)",
            "d:/SynchCore/tb/vectors/stimulus_case6.txt",
            "d:/SynchCore/tb/vectors/expected_case6.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 7: Intermediate Negative CFO (-0.03 Rsym = -937.5 kHz, SNR = 15 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 7: Intermediate Negative CFO (-0.03 Rsym, SNR = 15 dB)",
            "d:/SynchCore/tb/vectors/stimulus_case7.txt",
            "d:/SynchCore/tb/vectors/expected_case7.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 8: Low SNR Condition (+0.02 Rsym = +625 kHz, SNR = 6 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 8: Low SNR Condition (+0.02 Rsym, SNR = 6 dB)",
            "d:/SynchCore/tb/vectors/stimulus_case8.txt",
            "d:/SynchCore/tb/vectors/expected_case8.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 9: Autonomous Mode A Preamble Detection (+0.03 Rsym, SNR = 12 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 9: Autonomous Mode A (+0.03 Rsym, SNR = 12 dB)",
            "d:/SynchCore/tb/vectors/stimulus_case9.txt",
            "d:/SynchCore/tb/vectors/expected_case9.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 10: Autonomous Mode A High Negative CFO (-0.08 Rsym, SNR = 14 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 10: Autonomous Mode A (-0.08 Rsym, SNR = 14 dB)",
            "d:/SynchCore/tb/vectors/stimulus_case10.txt",
            "d:/SynchCore/tb/vectors/expected_case10.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 11: Streaming with Invalid-Sample Gaps (+0.04 Rsym, SNR = 20 dB)
        // ---------------------------------------------------------------------
        run_vector_test(
            "TEST CASE 11: Streaming with 50% Gaps (+0.04 Rsym, SNR = 20 dB)",
            "d:/SynchCore/tb/vectors/stimulus_case11.txt",
            "d:/SynchCore/tb/vectors/expected_case11.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 12: Consecutive Back-to-Back Bursts (Burst 1 -> Burst 2)
        // ---------------------------------------------------------------------
        $display("\n------------------------------------------------------------");
        $display("Running: TEST CASE 12: Consecutive Back-to-Back Bursts");
        $display("------------------------------------------------------------");
        run_vector_test(
            "TEST CASE 12 (Sub-Burst 1): First Burst (+0.05 Rsym)",
            "d:/SynchCore/tb/vectors/stimulus_case2.txt",
            "d:/SynchCore/tb/vectors/expected_case2.txt"
        );
        repeat (10) @(posedge clk);
        run_vector_test(
            "TEST CASE 12 (Sub-Burst 2): Consecutive Burst (-0.05 Rsym)",
            "d:/SynchCore/tb/vectors/stimulus_case3.txt",
            "d:/SynchCore/tb/vectors/expected_case3.txt"
        );

        // ---------------------------------------------------------------------
        // TEST CASE 13: Mid-Stream Reset Handling Verification
        // ---------------------------------------------------------------------
        $display("\n------------------------------------------------------------");
        $display("Running: TEST CASE 13: Mid-Stream Reset & Abort Verification");
        $display("------------------------------------------------------------");
        @(posedge clk);
        burst_start <= 1'b1;
        @(posedge clk);
        burst_start <= 1'b0;
        str_out_valid <= 1'b1;
        preamble_enable <= 1'b1;
        repeat (50) @(posedge clk);
        // Inject mid-stream abort (deassert preamble_enable, pulse burst_start)
        preamble_enable <= 1'b0;
        burst_start <= 1'b1;
        @(posedge clk);
        burst_start <= 1'b0;
        repeat (20) @(posedge clk);
        if (dut.state_r == dut.STATE_SEARCHING) begin
            $display("  DUT successfully aborted active accumulation and returned to STATE_SEARCHING. PASSED.");
            test_pass_count++;
        end else begin
            $display("  DUT failed to return to searching on reset! FAILED.");
            test_fail_count++;
        end

        // ---------------------------------------------------------------------
        // Final Verification Summary
        // ---------------------------------------------------------------------
        $display("\n========================================================================");
        $display("   TESTBENCH VERIFICATION SUMMARY                                       ");
        $display("========================================================================");
        $display("   Total Tests Run : %0d", test_pass_count + test_fail_count);
        $display("   Tests Passed    : %0d", test_pass_count);
        $display("   Tests Failed    : %0d", test_fail_count);
        $display("========================================================================");

        if (test_fail_count == 0) begin
            $display("   >>> ALL SYSTEMVERILOG RTL TESTS PASSED ACCORDING TO SPECIFICATION <<<");
            $display("   >>> BIT-EXACT ALIGNMENT CONFIRMED WITH MATLAB GOLDEN REFERENCES   <<<");
        end else begin
            $display("   >>> SOME RTL TESTS FAILED - REVIEW LOGS <<<");
        end
        $display("========================================================================\n");

        $finish;
    end

endmodule
